import type { CalendarDate, GoodUnit } from '@terra-scutum/sim';
import en from '../../../../locales/en.json';
import enMap from '../../../../locales/en.map.json';

/**
 * The small translation layer. All player-facing text lives in `locales/`:
 * `en.json` (written by hand) and `en.map.json` (names of countries,
 * provinces, regions and sea zones, generated by the map import). Code refers
 * to texts by key. Other languages can be added later by loading other files.
 */
export type TranslationKey = keyof typeof en;
export type TextParams = Readonly<Record<string, string | number>>;

const texts: Readonly<Record<string, string>> = { ...enMap, ...en };

function fill(text: string, params: TextParams | undefined): string {
  if (!params) return text;
  return text.replace(/\{([A-Za-z][A-Za-z0-9]*)\}/g, (placeholder, name: string) =>
    name in params ? String(params[name]) : placeholder,
  );
}

/** The text for a key, with `{placeholders}` filled in from `params`. */
export function t(key: TranslationKey, params?: TextParams): string {
  return fill(texts[key], params);
}

/**
 * Like `t`, for keys that arrive as plain strings from the sim (events,
 * command refusals, errors). An unknown key is shown as the key itself, so a
 * missing text is easy to spot.
 */
export function tKey(key: string, params?: TextParams): string {
  return Object.hasOwn(texts, key) ? fill(texts[key], params) : key;
}

/** An area as the player sees it, for example "17,033 km²" (one decimal below 10 km²: "0.5 km²"). */
export function formatArea(areaKm2: number): string {
  const area =
    areaKm2 < 10
      ? areaKm2.toLocaleString('en', { maximumFractionDigits: 1 })
      : Math.round(areaKm2).toLocaleString('en');
  return t('AREA_VALUE', { area });
}

/** A date as the player sees it, for example "1 January 2025". */
export function formatDate(date: CalendarDate): string {
  return t('DATE_FORMAT', {
    day: date.day,
    month: tKey(`MONTH_${date.month}`),
    year: date.year,
  });
}

/** Three significant digits, for example 83.5, 286 or 1.46. */
const threeDigits = (value: number) => value.toLocaleString('en', { maximumSignificantDigits: 3 });

/**
 * A number of people as the player sees it: "1.46 billion", "83.5 million",
 * or the exact number below a million ("41,024").
 */
export function formatPopulation(people: number): string {
  if (people >= 1e9) return t('NUMBER_BILLION', { value: threeDigits(people / 1e9) });
  if (people >= 1e6) return t('NUMBER_MILLION', { value: threeDigits(people / 1e6) });
  return Math.round(people).toLocaleString('en');
}

/** An amount of money given in millions of dollars: "$30.9 trillion", "$921 billion", "$300 million". */
export function formatMoneyMillions(millions: number): string {
  const amount =
    millions >= 1e6
      ? t('NUMBER_TRILLION', { value: threeDigits(millions / 1e6) })
      : millions >= 1e3
        ? t('NUMBER_BILLION', { value: threeDigits(millions / 1e3) })
        : t('NUMBER_MILLION', { value: threeDigits(millions) });
  return t('MONEY_VALUE', { amount });
}

/** An amount of money in dollars, to the dollar: "$61,271". */
export function formatMoney(dollars: number): string {
  return t('MONEY_VALUE', { amount: Math.round(dollars).toLocaleString('en') });
}

/** A number of people in a table: "1.46B", "83.5M", "365k", "842". */
export function formatPeopleShort(people: number): string {
  if (people >= 1e9) return t('NUMBER_SHORT_BILLION', { value: threeDigits(people / 1e9) });
  if (people >= 1e6) return t('NUMBER_SHORT_MILLION', { value: threeDigits(people / 1e6) });
  if (people >= 1e4) return t('NUMBER_SHORT_THOUSAND', { value: threeDigits(people / 1e3) });
  return Math.round(people).toLocaleString('en');
}

/** An amount of money in a table: "$1.07B", "$1.2M", "$64.7k", "$518". */
export function formatMoneyShort(dollars: number): string {
  const amount =
    dollars >= 1e9
      ? t('NUMBER_SHORT_BILLION', { value: threeDigits(dollars / 1e9) })
      : dollars >= 1e6
        ? t('NUMBER_SHORT_MILLION', { value: threeDigits(dollars / 1e6) })
        : dollars >= 1e4
          ? t('NUMBER_SHORT_THOUSAND', { value: threeDigits(dollars / 1e3) })
          : Math.round(dollars).toLocaleString('en');
  return t('MONEY_VALUE', { amount });
}

/** A share (0–1) as a percentage: "4.2 %", or "100 %" without decimals when asked. */
export function formatPercent(share: number, decimals = 1): string {
  return t('PERCENT_VALUE', {
    value: (share * 100).toLocaleString('en', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    }),
  });
}

/** People per km²: "237 per km²", "3.4 per km²", "0.03 per km²". */
export function formatDensity(perKm2: number): string {
  const value =
    perKm2 >= 100
      ? Math.round(perKm2).toLocaleString('en')
      : perKm2.toLocaleString('en', { maximumSignificantDigits: 2 });
  return t('DENSITY_VALUE', { value });
}

/**
 * An amount of a good as the player sees it (F07): real units, shortened so
 * the numbers stay small (designer decision). Tonnes: "950 t", "5 kt",
 * "1.4 Mt"; megawatt-hours: "25 MWh", "2.5 GWh", "1.1 TWh".
 */
export function formatAmount(amount: number, unit: GoodUnit): string {
  const steps =
    unit === 't'
      ? (['AMOUNT_T', 'AMOUNT_KT', 'AMOUNT_MT', 'AMOUNT_GT'] as const)
      : (['AMOUNT_MWH', 'AMOUNT_GWH', 'AMOUNT_TWH'] as const);
  let step = 0;
  let value = Math.abs(amount);
  // 999.5 would read "1,000": move up a step from there.
  while (value >= 999.5 && step < steps.length - 1) {
    value /= 1000;
    step += 1;
  }
  const text =
    value >= 100 || (step === 0 && value >= 10)
      ? Math.round(value).toLocaleString('en')
      : threeDigits(value);
  return t(steps[step], { value: amount < 0 ? `−${text}` : text });
}
